var EXEC={ "growth-trace": function(inp){var n=inp.appends,cap=1,copies=0,len=0;
for(var i=0;i<n;i++){if(len===cap){copies+=cap;cap*=2;}len++;}
return {capacity:cap,copies:copies,length:len};} };
var MK={ "growth-trace": function(rnd){return {appends:5+((rnd()*16)|0)};} };
var TRACE_GROUP="memory-model";
var TRACE_TITLES={ "growth-trace": "dynamic-array growth" };
var P1={ "growth-trace": "A dynamic array starts empty with capacity 1 and doubles every time it fills up. This drill hands you {appends} appends and asks for the final capacity and the total number of element-copies performed across all resizes. Simulate it: walk the appends one by one, doubling (and counting the copy of every live element) exactly when the array is full." };
var P2={ "growth-trace": "The copy count is the heart of amortized analysis. Each resize copies every element, but after a resize to capacity C the next C appends are all free — so the expensive copies are spread thin. Work the drill by hand first: keep two running tallies (capacity, copies) and update them per append; the pattern of when resizes fire is the whole lesson." };
var P3={ "growth-trace": "After {appends} appends the array sits at capacity {capacity} with {copies} total element-copies. Notice copies < 2*appends always: n appends cost O(n) total, i.e. O(1) amortized each. Growing by a fixed increment instead would cost O(n^2) — the doubling is load-bearing." };
var PYPROG={ "growth-trace": "TRACE_INPUT = {input}\nn = TRACE_INPUT['appends']\ncap, copies, length = 1, 0, 0\nfor _ in range(n):\n    if length == cap:      # full: double and copy everything\n        copies += cap\n        cap *= 2\n    length += 1\nprint({'capacity': cap, 'copies': copies, 'length': length})\n# capacity/copies after n appends from empty, doubling growth\n" };
var SIG=false;
var GEN_SRC="signature-generated-sample";
